    semester_id, course_id, professor_id, section_no, capacity, classroom, status,
    midterm_ratio, final_ratio, assignment_ratio, attendance_ratio, syllabus
) VALUES (
    #{semesterId}, #{courseId}, (SELECT id FROM professors WHERE user_id = #{professorId}), #{sectionNo}, #{capacity}, #{classroom}, 'OPEN',
    #{midtermRatio}, #{finalRatio}, #{assignmentRatio}, #{attendanceRatio}, #{syllabus}
)
